  ('stevens-pass-washington', '12A', 'Stevens Pass', 'United States', 'Deep Cascade powder two hours from Seattle', 'live', 'verified', 'northernLights', 'The Pacific Northwest', '{"ski","family","culinary","romance"}', '{}', '{"essential","comfort","luxury","ultra"}', null, 'core', '{"key_facts":["Cascade-crest day-use mountain on US-2, ~65 mi/~2 hr NE of Seattle; Vail Resorts-operated (acquired 2018), on the Epic Pass (unlimited)","~1,125 skiable acres, 52 trails, 13 lifts, base 4,061 ft / summit 5,845 ft / ~1,784 ft vertical, ~460 in avg snowfall; ~11% beginner / 54% intermediate / 35% advanced","7th Heaven Chair (two-seat Riblet) billed as America''s steepest lift; Mill Valley ''backside'' (min elev ~3,821 ft)","Night skiing Wed-Sun to 10 p.m.; no slopeside village (day lodges: Granite Peaks Lodge + Creek Lodge)","Stevens Pass Nordic Center: ~30 km groomed classic/skate + ~10 km snowshoe, Lower Mill Valley ~5 mi east (Cascade Depot, Thu-Sun)","Leavenworth (Bavarian village ~35 mi east on US-2) = lodging/culinary/romance base; Christmas Lighting + Oktoberfest town-scale peaks","2025/26 opened Dec 5, 2025; Tunnel Creek backcountry (off-boundary) is serious avalanche terrain (2012 fatal slide)"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"Nearest ERs: Cascade Medical (Leavenworth, critical-access, ~35 mi E); EvergreenHealth Monroe (~40 mi W); Confluence Health/Central Washington Hospital (Wenatchee, larger trauma, ~35 mi SE); serious cases transfer to Wenatchee/Seattle; backcountry via county SAR / 911","malaria":"none","yellow_fever":"not required","activity_note":"WSDOT US-2 pass driving + Caltrans-style chain control + winter-long avalanche control (''Old Faithful'' zone, closures held at summit MP64/Scenic MP56); AVALANCHE beyond ropes incl. Tunnel Creek zone (NWAC bulletin, guide + beacon/probe/shovel); heavy maritime ''Cascade Concrete'' + tree-well/snow-immersion risk; fast Pacific storms/whiteout + wind-hold (7th Heaven); night-ski low light. Altitude LOW (base ~4,000 ft) — AMS not a concern","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb) + every weekend (Seattle weekend mountain) + powder days; Leavenworth Dec Christmas-Lighting weekends stack on top","shoulder":"early season (early-mid Dec), Jan weekdays, late Mar-Apr spring corn; Leavenworth festival calendar carries off-snow shoulder","green":"May-mid Nov (ski area closed; Leavenworth runs as green-season town break)","booking_lead":"Christmas/NY + Leavenworth holiday-lights weekends 4-9 mo; Presidents''/Feb + peak-weekend ski 2-5 mo; ordinary weekends 2-8 wk; powder 1-7 days","off_season_specials":"spring-corn ski deals (late Mar-Apr); weekday ski packages; early-season pre-Christmas ski; Leavenworth year-round festival/wine/river calendar as true shoulder engine","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms; Leavenworth Christmas Lighting (Dec wknds) + Oktoberfest (autumn) (verify 2026/27)","fire_date":"FIRE ski mid-late Mar (ahead of Apr-Jun early-bird) + late Aug-early Sep (ahead of Sep-Nov fall wave); layer Leavenworth Christmas-Lights (~Sep) + Oktoberfest (~Jul) getaway campaigns"},"jewels":[{"name":"Ride the 7th Heaven Chair — America''s steepest lift","status":"future","tier":"comfort","price_band":"~USD 99-189/day window; Epic Day advance cheaper","timing":"ski ~Dec-Apr, snow-dependent; in-bounds patrolled","draw_rank":1,"hook":"a survivor two-seat Riblet up to Stevens'' expert shoulder","si":"ski","blurb":"a survivor two-seat Riblet up to Stevens'' expert shoulder","when":"ski ~Dec-Apr, snow-dependent; in-bounds patrolled","commission":"DM