  ('white-mountains-new-hampshire', '12A', 'White Mountains (Loon + Cannon + Bretton Woods)', 'United States', 'Three White Mountains classics in the shadow of Mount', 'live', 'verified', 'northernLights', 'New England', '{"ski","family","ultra","culinary","romance","wellness"}', '{}', '{"essential","comfort","premier","luxury","ultra"}', null, 'anchor', '{"key_facts":["Three NH White Mountains ski areas folded — per-area stats in folded_in: Loon (family, Boyne/Ikon), Cannon (state-owned, North America''s first aerial tramway 1938, Mittersill, Bode Miller''s home hill), Bretton Woods (NH''s largest, Omni Mount Washington Hotel 1902, host of the 1944 Bretton Woods Conference founding the IMF + World Bank)","Mount Washington = 6,288 ft (highest peak in the Northeast), ''home of the world''s worst weather''; 231 mph gust recorded 1934 (among the highest surface wind speeds ever measured); its shadow defines the region''s cold/wind","TARGETED avalanche zone = Presidential Range / Tuckerman + Huntington Ravine on Mount Washington (MWAC-gated backcountry); in-bounds avalanche risk at all three areas otherwise low","Nearest ER: Littleton Regional Healthcare (Level III trauma, closest to Cannon + Bretton Woods) + Speare Memorial Hospital (Plymouth, closest to Loon); serious trauma to Dartmouth Hitchcock (Lebanon) or Boston"],"safety":{"emergency":"911 (police/fire/ambulance/rescue dispatch, nationwide)","hospital":"Littleton Regional Healthcare (24/7 ER, region''s only Level III trauma — closest to Cannon + Bretton Woods) + Speare Memorial (Plymouth, 24/7 ER — closest to Loon); serious trauma to Dartmouth Hitchcock (Lebanon) or Boston; backcountry via NH Fish and Game + AMC/USFS on Mount Washington / 911","malaria":"none","yellow_fever":"not required","activity_note":"EXTREME COLD + WIND-CHILL (acute — Mount Washington''s shadow, ''world''s worst weather'', 231 mph gust 1934; Cannon + Bretton Woods bitterly cold/windy; frostbite fast, wind holds); ICE/HARDPACK + freeze-thaw ''boilerplate'' (Cannon natural-snow glazes hardest); TARGETED avalanche flag — Presidential Range / Tuckerman + Huntington Ravine = the one genuine Eastern avalanche zone (MWAC before backcountry/Tuckerman spring, guide + beacon/probe/shovel); LOW in-bounds avalanche; Franconia Notch Parkway (I-93) + Rte 302 winter driving (511NH/newengland511)","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/usa","read":"2026-09-01T16:18:24Z","page_updated":"2026-08-18T10:29:04+01:00","source_country":"usa","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely"},"timing":{"peak":"High winter (Christmas/NY, MLK + Presidents'' wknds, Feb vacation week) + strong weekend peaks (Boston drive market, Loon on I-93); fall foliage (late Sep-mid Oct) for Cannon Tramway + Omni","shoulder":"early season (mid-late Dec), Jan weekdays, Mar-early Apr spring corn","green":"mid-Apr-May + Nov-early Dec (between-season lulls; reduced ops — verify)","booking_lead":"Christmas/NY + Omni + Feb vacation week 4-10 mo; Presidents''/Feb 2-5 mo; foliage 3-8 mo; spring-corn/shoulder 1-4 wk (drive-in market)","off_season_specials":"spring-corn deals (Mar-Apr); summer + fall-foliage at the Omni + Cannon Tramway; Nordic + spa; midweek value","event_peaks":"Christmas/NY, MLK + Presidents'' wknds, US school half-terms, fall foliage, spring closing/pond-skim (verify 2027)","fire_date":"FIRE ski mid-late Mar + late Aug-early Sep; market summer/foliage Omni + Cannon Tramway by Jan-Feb"},"jewels":[{"name":"Ride North America''s first aerial tramway at Cannon","status":"future","tier":"comfort","price_band":"~USD 79-139/day (Cannon value)","timing":"ski ~mid-Dec-Apr","draw_rank":1,"hook":"the Cannon Tramway has climbed to the summit since 1938","si":"ski","blurb":"the Cannon Tramway has climbed to the summit since 1938","when":"ski ~mid-Dec-Apr","commission":"DMC/ski-op 10-20%","wells":["activities"],"wells_bas